package com.campusvote.model;
import jakarta.persistence.*;
@Entity @Table(name="candidates") public class Candidate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String name; @Column(length=1200) String manifesto; String department; String year; String photoUrl; @ManyToOne(fetch=FetchType.LAZY) Post post; public Candidate(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String x){name=x;} public String getManifesto(){return manifesto;} public void setManifesto(String x){manifesto=x;} public String getDepartment(){return department;} public void setDepartment(String x){department=x;} public String getYear(){return year;} public void setYear(String x){year=x;} public String getPhotoUrl(){return photoUrl;} public void setPhotoUrl(String x){photoUrl=x;} public Post getPost(){return post;} public void setPost(Post x){post=x;} }
